const stage = ComponentRegistry.get('CreateGameStage');
const original = stage.factory();
ComponentRegistry.register('CreateGameStage', props => {
  const background = document.createElement('div');
  background.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;background-size:cover;background-position:center;background-repeat:no-repeat;';
  createRenderEffect(() => {
    const texture = civilizationBackgroundTexture(props.backgroundImage);
    const custom = texture !== props.backgroundImage;
    background.style.display = custom ? 'block' : 'none';
    background.style.backgroundImage = custom ? `url("${texture}")` : '';
    background.style.opacity = String(props.backgroundOpacity ?? 0.15);
  });
  return [background, original(props)];
}, stage.overridePriority + 1);
